using System.Text.Json;
using PharmaAccess.Application.MachineLearning;
namespace PharmaAccess.Llm;
public sealed class HistoricalReplayExplanationService(IHistoricalPredictionReplayService replay,ILanguageModelClient languageModel,TimeProvider clock):IHistoricalReplayExplanationService
{
 public async Task<HistoricalReplayExplanationResponse> ExplainAsync(HistoricalReplayExplanationRequest request,CancellationToken token=default){var result=await replay.ReplayAsync(new(request.GenericLaunchId,request.AsOfQuarter),token);if(!languageModel.IsAvailable)throw new InvalidOperationException("Gemini explanation is unavailable. Configure a Gemini API key; scoring remains available.");var grounding=new{result.Mode,result.LaunchDisplayIdentifier,result.GenericLaunchId,result.AsOfQuarter,result.TargetQuarter,Jurisdictions=result.RankedStates.Take(15).Select(x=>new{x.StateCode,x.StateName,x.Rank,x.Probability,x.AboveSelectedThreshold}),result.SelectedThreshold,result.ModelVersion,result.GovernanceStatus,result.DatasetVersion,result.FeatureSetVersion};var prompt="Explain immutable structured output. Explicitly state: historical research replay; model-estimated probability; target is first observed eligible Medicaid utilization in T+1; not a commercial launch recommendation; does not establish patient consumption; not causal; ValidationSelected and not production approved. Never alter/invent probabilities or ranks, add/remove jurisdictions, claim availability/causality, turn threshold into a recommendation, or invent feature drivers. Grounding JSON: "+JsonSerializer.Serialize(grounding);var text=await languageModel.GenerateAsync(prompt,token);return new(text,languageModel.Provider,languageModel.Model,clock.GetUtcNow().UtcDateTime,"StructuredPredictionOnly");}
}
